  "knowledge": "Treatment Adherence Rate (TAR)",
  "description": "Measures the proportion of patients with high or medium treatment adherence at a facility.",
  "definition": "TAR = \frac{\text{Number of outcomes with Treatment Adherence of 'High', 'Medium', or 'Compliant'}}{\text{Total number of treatment outcomes}} \text{ for a given facility.}"
}

