  "knowledge": "Facility Resource Adequacy Index (FRAI)",
  "description": "Quantifies the adequacy of community resources available at a facility.",
  "definition": "FRAI = \text{The average of resource scores, where the score is 3 for 'Comprehensive' or 'Extensive' community resources, 2 for 'Adequate', and 1 for 'Limited'.}"
}

