  "knowledge": "Community Resources",
  "description": "Illustrates the value of community resource availability.",
  "definition": "Ranges from Limited to Comprehensive/Extensive. Limited indicates few resources, Adequate indicates sufficient resources, and Comprehensive/Extensive indicates robust resources."
}

